import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const keilPhysicalScenarios=['keil-lancelot','keil-lia','keil-hidden','keil-unrelated','keil-multi','keil-self','keil-follower','keil-third','keil-canceled','keil-refill','keil-growth','keil-transform','keil-revive'] as const;
export type KeilPhysicalScenario=typeof keilPhysicalScenarios[number];
export function isKeilPhysicalScenario(name:string):name is KeilPhysicalScenario{return (keilPhysicalScenarios as readonly string[]).includes(name);}
export function keilMode(name:KeilPhysicalScenario){return{multi:name==='keil-multi',follower:name==='keil-follower'||name==='keil-third',owner:name==='keil-self'||name==='keil-follower'?1:3,attack:name==='keil-multi'?'a2-p10-r2c1':'a2-p10-r1c3'};}
/** Initial deals/training only, followed by real setup, target reveal, chant and turn cycle. */
export function makeKeilPhysicalScenario(name:KeilPhysicalScenario,players:{id:string;name:string}[]){
 let s=createGame(players,entropy(),{startingSeat:0});const m=keilMode(name),[a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,['魔導王ガイナス',name==='keil-lia'?'リーア姫':name==='keil-unrelated'?'有翼人のティア':'聖騎士ランスロット',name==='keil-transform'?'リーア姫':'大神官ジル',name==='keil-revive'?'邪祭ウーノス':'侍大将のシン'][i]!);for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};if(name==='keil-revive')s.players[b]!.permanent!.endurance=100+4-gameStats(s,b).endurance;
 const keep=[takeCard(s,a,m.attack),takeCard(s,a,'a2-p24-r1c2'),takeCard(s,a,'a2-p02-r2c3'),takeCard(s,players[m.owner]!.id,'a2-p01-r3c1'),takeCard(s,d,'a2-p04-r3c2'),takeCard(s,d,'a2-p13-r3c1')];if(m.follower)keep.push(takeCard(s,b,'a2-p20-r3c1'));for(const p of players)trimHand(s,p.id,...keep);
 let blood:string|undefined;if(name==='keil-refill'||name==='keil-growth'){blood=takeCard(s,a,name==='keil-growth'?'a2-p01-r1c2':'a2-p01-r1c3');s.players[a]!.hand=s.players[a]!.hand.filter(id=>id!==blood);}const ordinary=s.deck.filter(id=>getAction(id)!.category!=='open'),opens=s.deck.filter(id=>getAction(id)!.category==='open'),prefix=players.reduce((n,p)=>n+Math.max(0,5-s.players[p.id]!.hand.length),0)+1+(name==='keil-growth'?1:0);s.deck=blood?[...ordinary.slice(0,prefix),blood,...ordinary.slice(prefix),...opens]:[...ordinary,...opens];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`KEIL_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('KEIL_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('KEIL_FIXTURE_CARDS');}
 for(const id of [a,b,c,d]){if(id===b&&m.follower)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p20-r3c1'});act(id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(name!=='keil-hidden')act(b,{type:'REVEAL_CHARACTER'});while(s.windows?.length){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}act(a,{type:'CHANT',cardInstanceId:m.attack});
 for(let n=0;n<100;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===a)break;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(id=>!keep.includes(id)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('KEIL_FIXTURE_PHASE');}
 if(s.phase!=='action'||s.seatOrder[s.turnSeat]!==a)throw Error('KEIL_FIXTURE_TURN');if(blood&&s.deck[name==='keil-growth'?1:0]!==blood)throw Error('KEIL_REFILL_PREFIX');return s;
}
